   "code": "// Soft TTL: serve stale while one request refreshes in the background\nasync function getWithSoftTtl(key, softSec, hardSec, load) {\n  const raw = await redis.get(key);\n  if (raw) {\n    const { v, freshUntil } = JSON.parse(raw);\n    if (Date.now() > freshUntil && await redis.set(`lock:${key}`, '1', { NX: true, EX: 10 })) {\n      load().then(nv => redis.set(key, JSON.stringify({ v: nv, freshUntil: Date.now() + softSec * 1000 }), { EX: hardSec }))\n            .catch(() => {})                                 // keep serving stale on error\n            .finally(() => redis.del(`lock:${key}`));\n    }\n    return v;                                               // stale is fine for a while\n  }\n  const v = await load();\n  await redis.set(key, JSON.stringify({ v, freshUntil: Date.now() + softSec * 1000 }), { EX: hardSec });\n  return v;\n}\n\n// Negative caching: remember \"not found\" for a short time\nasync function getUser(id) {\n  const hit = await redis.get(`user:${id}`);\n  if (hit === 'null') return null;\n  if (hit) return JSON.parse(hit);\n  const u = await db.oneOrNone('SELECT * FROM users WHERE id = $1', [id]);\n  await redis.set(`user:${id}`, JSON.stringify(u), { EX: u ? 300 : 30 });\n  return u;\n}",
